require_once 'config.php'; require_auth(); ensure_schema(); $pdo=db(); $pageTitle='Búsqueda global'; $q=trim((string)($_GET['q']??'')); $clients=[];$vehicles=[];$orders=[];$parts=[];
if($q!==''){ $like='%'.$q.'%'; $st=$pdo->prepare('SELECT id,name,phone,dni FROM clients WHERE active=1 AND (name LIKE ? OR phone LIKE ? OR dni LIKE ?) ORDER BY name LIMIT 20');$st->execute([$like,$like,$like]);$clients=$st->fetchAll();
$st=$pdo->prepare('SELECT v.*,c.name client_name FROM vehicles v JOIN clients c ON c.id=v.client_id WHERE v.active=1 AND (v.plate LIKE ? OR v.engine_number LIKE ? OR v.chassis_number LIKE ? OR v.brand LIKE ? OR v.model LIKE ?) ORDER BY v.brand,v.model LIMIT 20');$st->execute([$like,$like,$like,$like,$like]);$vehicles=$st->fetchAll();
$st=$pdo->prepare('SELECT wo.id,wo.code,wo.current_status,c.name client_name,v.brand,v.model,v.plate FROM work_orders wo JOIN clients c ON c.id=wo.client_id JOIN vehicles v ON v.id=wo.vehicle_id WHERE wo.code LIKE ? OR c.name LIKE ? OR v.plate LIKE ? OR v.engine_number LIKE ? OR v.chassis_number LIKE ? ORDER BY wo.updated_at DESC LIMIT 30');$st->execute([$like,$like,$like,$like,$like]);$orders=$st->fetchAll();
$st=$pdo->prepare('SELECT id,name,sku,stock,sell_price FROM parts WHERE active=1 AND (name LIKE ? OR sku LIKE ? OR category LIKE ?) ORDER BY name LIMIT 20');$st->execute([$like,$like,$like]);$parts=$st->fetchAll(); }
include 'partials/header.php'; ?>
