<?php $groups=[['Clientes',$clients,'client_view.php'],['Motos',$vehicles,'client_view.php'],['Órdenes',$orders,'order_view.php'],['Repuestos',$parts,'parts.php']]; foreach($groups as [$title,$rows,$url]):?><section class="card span6"><div class="card-header"><div><h2><?=h($title)?></h2><p><?=count($rows)?> resultado<?=count($rows)==1?'':'s'?></p></div></div><?php if(!$rows):?><p class="muted">Sin resultados.</p><?php else:?><div class="timeline"><?php foreach($rows as $r):?><div class="event"><strong><?php if($title==='Clientes'):?><a href="client_view.php?id=<?=(int)$r['id']?>"><?=h($r['name'])?></a><?php elseif($title==='Motos'):?><a href="client_view.php?id=<?=(int)$r['client_id']?>"><?=h($r['brand'].' '.$r['model'])?></a><?php elseif($title==='Órdenes'):?><a href="order_view.php?id=<?=(int)$r['id']?>"><?=h($r['code'])?></a><?php else:?><a href="parts.php?view=<?=(int)$r['id']?>"><?=h($r['name'])?></a><?php endif;?></strong><small class="muted"><?php if($title==='Clientes'):?><?=h($r['phone'])?> · <?=h($r['dni']?:'Sin DNI')?><?php elseif($title==='Motos'):?><?=h($r['plate'])?> · <?=h($r['client_name'])?><?php elseif($title==='Órdenes'):?><?=h($r['client_name'].' · '.$r['brand'].' '.$r['model'].' · '.$r['plate'])?><?php else:?><?=h(($r['sku']?:'Sin SKU').' · Stock '.units($r['stock']).' · '.money($r['sell_price']))?><?php endif;?></small></div><?php endforeach;?></div><?php endif;?></section><?php endforeach;?></div><?php endif;?><?php include 'partials/footer.php'; ?>
